import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {TRAINING_PLAN,PLAN_REVISION,updateClientPlanState} from '../training-plan.js';
import {normalizePlan,normalizeState,parseImport,setDone} from '../core.js';

// Captured from the exact published 3.5 source, not regenerated by the new code.
const previousPlan=JSON.parse(readFileSync(new URL('./fixtures/plan-v35.json',import.meta.url),'utf8'));
const previousState=()=>normalizeState({version:1,plan:previousPlan,progress:{},updatedAt:'2026-11-10T20:00:00Z'});
const currentPlan=normalizePlan(TRAINING_PLAN);
const find=(state,id)=>state.plan.workouts.find(w=>w.id===id);
const current=id=>currentPlan.workouts.find(w=>w.id===id);

test('3.5 gains the new future instructions without mutating its input or progress',()=>{
  const previous=previousState();
  previous.progress['tpab-2026-11-14-b']={done:false,steps:{run:true},note:'Meine Notiz bleibt.\nÄ, ö, ß und 🏃',completedAt:null};
  const before=JSON.stringify(previous),next=updateClientPlanState(previous);
  assert.equal(PLAN_REVISION,4);
  assert.equal(JSON.stringify(previous),before);
  assert.equal(next.plan.revision,PLAN_REVISION);
  assert.equal(next.plan.workouts.length,91);
  assert.deepEqual(next.progress,previous.progress);
  assert.equal(next.updatedAt,previous.updatedAt);
  for(const original of previous.plan.workouts){
    assert.deepEqual(find(next,original.id),original.date<'2026-11-11'?original:current(original.id),original.id);
  }
  assert.strictEqual(updateClientPlanState(next),next);
});

test('completed training and rest days retain their exact old workout and recorded progress',()=>{
  const previous=previousState();
  for(const id of ['tpab-2026-11-11-a','tpab-2026-11-14-b','tpab-2026-11-10-rest']){
    setDone(previous,id,true,'2026-11-10T20:01:00Z');
    previous.progress[id].note='Schon erledigt, nicht neu interpretieren.';
  }
  const next=updateClientPlanState(previous);
  for(const id of Object.keys(previous.progress)){
    assert.deepEqual(find(next,id),find(previous,id),id);
    assert.deepEqual(next.progress[id],previous.progress[id],id);
  }
  assert.deepEqual(find(next,'tpab-2026-11-21-b'),current('tpab-2026-11-21-b'));
});

test('custom exercises, moved sessions, extra sessions and intentional deletions survive unchanged',()=>{
  const previous=previousState();
  const edited=find(previous,'tpab-2026-11-21-b');
  edited.description='Eigene Absprache mit der Sportlehrkraft';
  edited.steps.push({id:'personal-drill',title:'Meine Übung',details:'Nur nach persönlicher Absprache.'});
  const moved=find(previous,'tpab-2026-11-18-a');
  moved.date='2026-11-19';moved.startTime='09:00';moved.endTime='10:00';
  const extra={...structuredClone(find(previous,'tpab-2026-11-20-rest')),id:'my-own-extra',title:'Eigene Ergänzung'};
  previous.plan.workouts.push(extra);
  previous.plan.workouts=previous.plan.workouts.filter(w=>!['tpab-2026-11-25-a','tpab-2026-11-29-rest'].includes(w.id));
  previous.progress[moved.id]={done:false,steps:{},note:'Termin verschoben',completedAt:null};
  const next=updateClientPlanState(previous);
  for(const w of [edited,moved,extra])assert.deepEqual(find(next,w.id),w);
  assert.deepEqual(next.plan.workouts.map(w=>w.id),previous.plan.workouts.map(w=>w.id));
  assert.equal(next.plan.workouts.some(w=>w.id==='tpab-2026-11-25-a'),false);
  assert.equal(next.plan.workouts.some(w=>w.id==='tpab-2026-11-29-rest'),false);
  assert.equal(next.plan.workouts.some(w=>w.date==='2026-11-18'),false);
  assert.deepEqual(next.progress,previous.progress);
});

test('custom plan metadata is retained including a description beginning like the old template',()=>{
  for(const previous of [previousState(),normalizeState({version:1,plan:JSON.parse(readFileSync(new URL('./fixtures/plan-v33.json',import.meta.url),'utf8')),progress:{}})]){
    previous.plan.title='Mein eigener Titel';
    previous.plan.description='Drei Trainingstage nach meiner eigenen Absprache.';
    previous.plan.targetDate='2027-07-17';previous.plan.targetLabel='Mein Termin';
    previous.plan.goalSummary='Eigene Zielnotiz';
    const next=updateClientPlanState(previous);
    for(const key of ['id','title','description','targetDate','targetLabel','goalSummary'])assert.equal(next.plan[key],previous.plan[key],key);
  }
});

test('a late installation preserves every earlier open day as history',()=>{
  for(const fixture of ['v33','v34','v35']){
    const previous=normalizeState({version:1,plan:JSON.parse(readFileSync(new URL(`./fixtures/plan-${fixture}.json`,import.meta.url),'utf8')),progress:{}});
    const next=updateClientPlanState(previous,'2026-12-01');
    for(const w of previous.plan.workouts.filter(w=>w.date<'2026-12-01'))assert.deepEqual(find(next,w.id),w,fixture+' '+w.id);
    assert.deepEqual(find(next,'tpab-2026-12-12-b'),current('tpab-2026-12-12-b'));
    assert.equal(next.plan.revision,PLAN_REVISION);
  }
});

test('unrelated, current and newer plan revisions are left untouched, even with missing dates',()=>{
  const unrelated=previousState();unrelated.plan.id='my-unrelated-plan';
  assert.strictEqual(updateClientPlanState(unrelated),unrelated);
  for(const revision of [PLAN_REVISION,PLAN_REVISION+1]){
    const state=previousState();state.plan.revision=revision;
    state.plan.workouts=state.plan.workouts.filter(w=>w.id!=='tpab-2026-11-25-a');
    assert.strictEqual(updateClientPlanState(state),state);
  }
});

test('JSON backup and restore retain completion, notes and existing legacy step checks',()=>{
  const previous=previousState();
  setDone(previous,'tpab-2026-11-11-a',true,'2026-11-10T20:01:00Z');
  previous.progress['tpab-2026-11-11-a'].note='Bereits erledigt';
  previous.progress['tpab-2026-11-14-b']={done:false,steps:{run:true},note:'Offener Termin mit Notiz',completedAt:null};
  const next=updateClientPlanState(previous);
  const restored=parseImport(JSON.stringify({kind:'pista-backup',state:next})).state;
  for(const [id,p] of Object.entries(previous.progress)){
    assert.equal(restored.progress[id].done,p.done);
    assert.equal(restored.progress[id].note,p.note);
    assert.equal(restored.progress[id].completedAt,p.completedAt);
    for(const [step,done] of Object.entries(p.steps))assert.equal(restored.progress[id].steps[step],done);
  }
  assert.strictEqual(updateClientPlanState(restored),restored);
});

test('one migrated state cannot mutate the canonical plan used by later migrations',()=>{
  const first=updateClientPlanState(previousState());
  const id='tpab-2026-11-14-b',original=structuredClone(current(id));
  find(first,id).steps[0].details='An edit in one independent state';
  const second=updateClientPlanState(previousState());
  assert.deepEqual(find(second,id),original);
  assert.deepEqual(normalizePlan(TRAINING_PLAN).workouts.find(w=>w.id===id),original);
});
